.fn{width:100%;max-width:760px}
.fn .ch-head{align-items:flex-start}
.fn .ch-big{display:flex;align-items:baseline;gap:8px;margin-top:4px;font-size:26px;font-weight:600;letter-spacing:-.02em;color:var(--text)}
.fn .ch-sub{font-size:12.5px;font-weight:500;color:var(--muted);letter-spacing:0}
.fn-plot{position:relative;height:190px;overflow:hidden}
.fn-plot svg{display:block;width:100%;height:100%;overflow:visible}
.fn-sep{stroke:var(--line);stroke-width:1}
.fn-prev{fill:var(--accent-hi);opacity:.16}
.fn-cur{fill:url(#fn-grad)}
.fn-col{fill:transparent;cursor:default;transition:fill .2s}
.fn-col:hover{fill:color-mix(in srgb,var(--text) 4%,transparent)}
.fn-labs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-top:14px;border-bottom:1px solid var(--line)}
.fn-lab{display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-width:0;padding:0 10px 10px}
.fn-lab + .fn-lab{border-left:1px solid var(--line)}
.fn-lab .mono-xs,.fn-lab b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.fn-lab .mono-xs{font-size:11px}
.fn-lab b{font-size:18px;font-weight:600;color:var(--text);letter-spacing:-.01em}
.fn-pc{align-self:flex-start;margin-top:2px;padding:1px 6px;font-family:var(--mono);font-size:10.5px;font-weight:700;color:var(--accent);background:var(--accent-bg)}
.fn-leg{display:flex;gap:16px;margin-top:10px;font-size:12px;color:var(--text-dim)}
.fn-leg span{display:inline-flex;align-items:center;gap:6px}
.fn-leg i{width:10px;height:10px}
.fn-leg i.cur{background:var(--accent-hi)}
.fn-leg i.prev{background:color-mix(in srgb,var(--accent-hi) 22%,var(--panel))}
[data-style="soft"] .fn-pc{border-radius:999px;font-family:var(--sans);font-weight:600}
[data-style="soft"] .fn-leg i{border-radius:3px}
/* funnel: labels, plot and legend share the title's left edge, with room under the legend */
.fn .fn-labs{margin:14px 16px 0}
.fn .fn-plot{margin:0 16px}
.fn .fn-leg{margin-top:12px;padding:0 16px 18px}
.fn .fn-lab:first-child{padding-left:0}

/* ---------- funnel chart ---------- */
{
  const plot = $('#fn-plot'), labs = $('#fn-labs'), STAGES = ['Visited','Signed up','Activated','Paid'];
  const DATA = { month:{ cur:[12400,6200,3720,1860], prev:[11800,5550,3110,1490] }, quarter:{ cur:[36800,17300,10900,5100], prev:[33900,15200,8960,4120] } };
  let mode = 'month', shown = { cur:[1,1,1,1], prev:[1,1,1,1] }, raf = null;
  const fmt = v => v >= 1000 ? (v / 1000).toFixed(v >= 100000 ? 0 : 1).replace(/\.0$/, '') + 'k' : String(v);
  function shape(vals, W, H, top){
    const n = vals.length, cw = W / n, max = vals[0], mid = top + (H - top) / 2, h = v => Math.max(6, v / max * (H - top) * .92);
    let up = `M0 ${mid - h(vals[0]) / 2}`, dn = [];
    for (let i = 0; i < n; i++){
      const x0 = i * cw, x1 = (i + 1) * cw, hh = h(vals[i]) / 2, flat = x0 + cw * .55;
      up += ` L${flat} ${mid - hh}`;
      if (i < n - 1){ const nh = h(vals[i + 1]) / 2; up += ` C${flat + cw * .3} ${mid - hh} ${x1 + cw * .05} ${mid - nh} ${x1 + cw * .2} ${mid - nh}`; } else up += ` L${x1} ${mid - hh}`;
    }
    for (let i = n - 1; i >= 0; i--){
      const x0 = i * cw, x1 = (i + 1) * cw, hh = h(vals[i]) / 2, flat = x0 + cw * .55;
      if (i === n - 1) dn.push(`L${x1} ${mid + hh} L${flat} ${mid + hh}`);
      else { const nh = h(vals[i + 1]) / 2; dn.push(`L${x1 + cw * .2} ${mid + nh} C${x1 + cw * .05} ${mid + nh} ${flat + cw * .3} ${mid + hh} ${flat} ${mid + hh}`); }
      if (i > 0) dn.push(`L${x0 + cw * .2} ${mid + hh}`); else dn.push(`L0 ${mid + hh}`);
    }
    return up + ' ' + dn.join(' ') + ' Z';
  }
  function draw(){
    const W = plot.clientWidth, H = plot.clientHeight, top = 8, d = DATA[mode];
    if (W < 60) return; const cw = W / 4;
    const cur = d.cur.map((v, i) => d.cur[0] * shown.cur[i] * (v / d.cur[0])), prev = d.prev.map((v, i) => v * shown.prev[i]);
    plot.innerHTML = `<svg viewBox="0 0 ${W} ${H}"><defs><linearGradient id="fn-grad" x1="0" x2="1"><stop offset="0" stop-color="var(--accent-hi)"/><stop offset="1" stop-color="var(--accent-hi)" stop-opacity=".72"/></linearGradient></defs>
      ${[1,2,3].map(i => `<line class="fn-sep" x1="${i * cw}" x2="${i * cw}" y1="0" y2="${H}"/>`).join('')}
      <path class="fn-prev" d="${shape(cur.map((v, i) => i ? cur[i - 1] : v), W, H, top)}"/><path class="fn-cur" d="${shape(cur, W, H, top)}"/>
      ${STAGES.map((s, i) => `<rect class="fn-col" x="${i * cw}" y="0" width="${cw}" height="${H}"><title>${s}: ${d.cur[i].toLocaleString('en-US')} kept${i ? `, ${(d.cur[i - 1] - d.cur[i]).toLocaleString('en-US')} dropped off` : ''}</title></rect>`).join('')}</svg>`;
    labs.innerHTML = STAGES.map((s, i) => `<div class="fn-lab"><span class="mono-xs">${s}</span><b>${fmt(d.cur[i])}</b><span class="fn-pc">${i ? Math.round(d.cur[i] / d.cur[i - 1] * 100) : 100}%</span></div>`).join('');
    $('#fn-total').firstChild.textContent = (d.cur[3] / d.cur[0] * 100).toFixed(1) + '%';
  }
  new ResizeObserver(draw).observe(plot);
  // grows in from the left when it comes into view, and morphs when the period changes
  const grow = () => { if (reduce){ draw(); return; } const t0 = performance.now(); cancelAnimationFrame(raf); const step = t => { const k = Math.min(1, (t - t0) / 900), e = 1 - Math.pow(1 - k, 3); shown = { cur:[1, 1, 1, 1].map((_, i) => i === 0 ? 1 : Math.pow(e, .6)), prev:[1, 1, 1, 1] }; draw(); if (k < 1) raf = requestAnimationFrame(step); }; raf = requestAnimationFrame(step); };
  whenSeen($('#c102'), grow);
  segInit($('#fn-seg'), v => { mode = v; grow(); Sound.play('tab'); });
}
